package com.mall.controller.admin;
import com.mall.common.result.Result; import com.mall.service.RiskControlService; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin/risk-controls") public class AdminRiskControlController { private final RiskControlService service; public AdminRiskControlController(RiskControlService service){this.service=service;} @PostMapping("/{userId}") public Result<Void> block(@AuthenticationPrincipal Long adminId,@PathVariable Long userId,@RequestBody RiskRequest r){service.block(userId,r.type(),r.reason(),adminId);return Result.success("已限制用户",null);}@DeleteMapping("/{userId}") public Result<Void> unblock(@PathVariable Long userId,@RequestParam(required=false)String type){service.unblock(userId,type);return Result.success("已解除限制",null);} public record RiskRequest(String type,String reason){} }
